 88	// An operation that fails while applying; its message is the reason.
 89	class OperationFailure extends Error {}
 90	
 91	// Follows tokens from root; returns the value they name or throws an OperationFailure.
 92	function resolve(root, tokens, notFound) {
 93	  let cur = root;
 94	  for (const t of tokens) {
 95	    if (Array.isArray(cur)) {
 96	      if (t === '-') throw new OperationFailure(notFound);
 97	      if (!INDEX_RE.test(t)) throw new OperationFailure('bad index');
 98	      if (Number(t) >= cur.length) throw new OperationFailure(notFound);
 99	      cur = cur[Number(t)];
100	    } else if (isObject(cur) && Object.hasOwn(cur, t)) {
101	      cur = cur[t];
102	    } else {
103	      throw new OperationFailure(notFound);
104	    }
105	  }
106	  return cur;
107	}
108	
109	// Follows all tokens of a non-empty path but the last; returns the parent and the last token.
110	function resolveParent(doc, path) {
111	  return [resolve(doc, path.slice(0, -1), 'path not found'), path[path.length - 1]];
112	}
113	
114	function addAt(doc, path, value) {
115	  if (path.length === 0) return value;
116	  const [parent, last] = resolveParent(doc, path);
117	  if (Array.isArray(parent)) {
118	    if (last === '-') {
119	      parent.push(value);
120	    } else if (!INDEX_RE.test(last)) {
121	      throw new OperationFailure('bad index');
122	    } else if (Number(last) > parent.length) {
123	      throw new OperationFailure('path not found');
124	    } else {
125	      parent.splice(Number(last), 0, value);
126	    }
127	  } else if (isObject(parent)) {
128	    setMember(parent, last, value);
129	  } else {
130	    throw new OperationFailure('path not found');
131	  }
132	  return doc;
133	}
134	
135	// Removes the value at a non-empty path that is known to exist.
136	function removeAt(doc, path) {
137	  const [parent, last] = resolveParent(doc, path);
138	  if (Array.isArray(parent)) parent.splice(Number(last), 1);
139	  else delete parent[last];
140	}
141	
142	// Replaces the value at a non-empty path that is known to exist, keeping its place.
143	function replaceAt(doc, path, value) {
144	  const [parent, last] = resolveParent(doc, path);
145	  if (Array.isArray(parent)) parent[Number(last)] = value;
146	  else setMember(parent, last, value);
147	  return doc;
148	}
149	
150	function applyOne(doc, op) {
151	  const path = parsePointer(op.path);
152	  switch (op.op) {
153	    case 'add':
154	      return addAt(doc, path, deepCopy(op.value));
155	    case 'remove':
156	      resolve(doc, path, 'path not found');
157	      removeAt(doc, path);
158	      return doc;
159	    case 'replace':
160	      if (path.length === 0) return deepCopy(op.value);
161	      resolve(doc, path, 'path not found');
162	      return replaceAt(doc, path, deepCopy(op.value));
163	    case 'move': {
164	      const from = parsePointer(op.from);
165	      const value = resolve(doc, from, 'from not found');
166	      if (op.from === op.path) return doc;
167	      // The form rules guarantee from is non-empty here (a "" from is a prefix of any other path).
168	      removeAt(doc, from);
169	      return addAt(doc, path, value);
170	    }
171	    case 'copy': {
172	      const value = deepCopy(resolve(doc, parsePointer(op.from), 'from not found'));
173	      return addAt(doc, path, value);
174	    }
175	    case 'test':
176	      if (!deepEqual(resolve(doc, path, 'path not found'), op.value)) {
177	        throw new OperationFailure('test failed');
178	      }
179	      return doc;
180	  }
181	}
182	
183	export function applyPatch(doc, patch) {
184	  if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
185	  const ops = [];
186	  for (let i = 0; i < patch.length; i++) {
187	    const op = patch[i];
188	    const reason = checkForm(op);
189	    if (reason) throw new PatchError(`operation ${i}: ${reason}`, i);
190	    ops.push(op);
191	  }
192	  let result = deepCopy(doc);
193	  for (let i = 0; i < ops.length; i++) {
194	    try {
195	      result = applyOne(result, ops[i]);
196	    } catch (err) {
197	      if (err instanceof OperationFailure) throw new PatchError(`operation ${i}: ${err.message}`, i);
198	      throw err;
199	    }
200	  }
201	  return result;
202	}
203	#!/usr/bin/env node
204	// Usage: node jsonpatch-cli.mjs <patch> [<doc>]
205	import fs from 'node:fs';
206	import { applyPatch, PatchError } from './jsonpatch.mjs';
207	
208	const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
209	const MAX_BYTES = 1048576;
210	const MAX_DEPTH = 1000;
211	const CHUNK = 65536;
212	
213	class CliError extends Error {
214	  constructor(message, code) {
215	    super(message);
216	    this.code = code;
217	  }
218	}
219	
220	function sleep(ms) {
221	  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
222	}
223	
224	// Reads at most MAX_BYTES + 1 bytes from fd; returns a Buffer or throws an fs error.
225	function readFd(fd) {
226	  const chunks = [];
227	  let total = 0;
228	  for (;;) {
229	    const buf = Buffer.alloc(CHUNK);
230	    let n;
231	    try {
232	      n = fs.readSync(fd, buf, 0, CHUNK, null);
233	    } catch (err) {
234	      if (err.code === 'EAGAIN') {
235	        sleep(10);
236	        continue;
237	      }
238	      throw err;
239	    }
240	    if (n === 0) break;
241	    chunks.push(buf.subarray(0, n));
242	    total += n;
243	    if (total > MAX_BYTES) break;
244	  }
245	  return Buffer.concat(chunks, total);
246	}
247	
248	function readError(name, reason) {
249	  return new CliError(`Error: ${name}: ${reason}`, 1);
250	}
251	
252	function isDirectory(path) {
253	  try {
254	    return fs.statSync(path).isDirectory();
255	  } catch {
256	    return false;
257	  }
258	}
259	
260	function readInput(arg) {
261	  if (arg === '-') {
262	    try {
263	      return readFd(0);
264	    } catch {
265	      throw readError('stdin', 'cannot read');
266	    }
267	  }
268	  let fd;
269	  try {
270	    fd = fs.openSync(arg, 'r');
271	  } catch (err) {
272	    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') throw readError(arg, 'no such file');
273	    throw readError(arg, err.code === 'EISDIR' || isDirectory(arg) ? 'is a directory' : 'cannot read');
274	  }
275	  try {
276	    if (fs.fstatSync(fd).isDirectory()) throw readError(arg, 'is a directory');
277	    return readFd(fd);
278	  } catch (err) {
279	    if (err instanceof CliError) throw err;
280	    throw readError(arg, err.code === 'EISDIR' ? 'is a directory' : 'cannot read');
281	  } finally {
282	    fs.closeSync(fd);
283	  }
284	}
285	
286	// Depth of a parsed JSON value, computed without recursion.
287	function depthOf(value) {
288	  let max = 0;
289	  const stack = [[value, 0]];
290	  while (stack.length) {
291	    const [v, d] = stack.pop();
292	    if (v === null || typeof v !== 'object') continue;
293	    const depth = d + 1;
294	    if (depth > max) max = depth;
295	    for (const child of Array.isArray(v) ? v : Object.values(v)) stack.push([child, depth]);
296	  }
297	  return max;
298	}
299	
300	function loadJson(arg) {
301	  const name = arg === '-' ? 'stdin' : arg;
302	  const bytes = readInput(arg);
303	  if (bytes.length > MAX_BYTES) throw readError(name, 'too large');
304	  let text;
305	  try {
306	    text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
307	  } catch {
308	    throw new CliError(`Error: ${name}: invalid UTF-8`, 3);
309	  }
310	  let value;
311	  try {
312	    value = JSON.parse(text);
313	  } catch {
314	    throw new CliError(`Error: ${name}: invalid JSON`, 3);
315	  }
316	  if (depthOf(value) > MAX_DEPTH) throw new CliError(`Error: ${name}: too deep`, 3);
317	  return value;
318	}
319	
320	function run(args) {
321	  if (args.length < 1 || args.length > 2) throw new CliError(USAGE, 2);
322	  const [patchArg, docArg = '-'] = args;
323	  if (patchArg === '-' && docArg === '-') throw new CliError(USAGE, 2);
324	  const patch = loadJson(patchArg);
325	  const doc = loadJson(docArg);
326	  try {
327	    return applyPatch(doc, patch);
328	  } catch (err) {
329	    if (err instanceof PatchError) throw new CliError(`Error: ${err.message}`, 4);
330	    throw err;
331	  }
332	}
333	
334	try {
335	  const result = run(process.argv.slice(2));
336	  process.stdout.write(JSON.stringify(result, null, 2) + '\n');
337	  process.exitCode = 0;
338	} catch (err) {
339	  if (!(err instanceof CliError)) throw err;
340	  process.stderr.write(err.message + '\n');
341	  process.exitCode = err.code;
342	}

