223	const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
224	const MAX_BYTES = 1048576;
225	const MAX_DEPTH = 1000;
226	
227	class InputError extends Error {
228	  constructor(message, exitCode) {
229	    super(message);
230	    this.exitCode = exitCode;
231	  }
232	}
233	
234	// Reads chunks from a stream until it ends or holds more than MAX_BYTES.
235	async function readCapped(stream) {
236	  const chunks = [];
237	  let total = 0;
238	  try {
239	    for await (const chunk of stream) {
240	      chunks.push(chunk);
241	      total += chunk.length;
242	      if (total > MAX_BYTES) return null;
243	    }
244	  } finally {
245	    stream.destroy();
246	  }
247	  return Buffer.concat(chunks);
248	}
249	
250	function openFile(path) {
251	  try {
252	    return fs.openSync(path, 'r');
253	  } catch (err) {
254	    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') throw new InputError('no such file', 1);
255	    let isDirectory = false;
256	    try {
257	      isDirectory = fs.statSync(path).isDirectory();
258	    } catch {
259	      // Fall through to "cannot read".
260	    }
261	    throw new InputError(isDirectory ? 'is a directory' : 'cannot read', 1);
262	  }
263	}
264	
265	async function readInput(arg) {
266	  const isStdin = arg === '-';
267	  const fd = isStdin ? 0 : openFile(arg);
268	  let bytes;
269	  try {
270	    bytes = await readCapped(fs.createReadStream(null, { fd, autoClose: !isStdin }));
271	  } catch (err) {
272	    throw new InputError(err.code === 'EISDIR' && !isStdin ? 'is a directory' : 'cannot read', 1);
273	  }
274	  if (bytes === null) throw new InputError('too large', 1);
275	  return bytes;
276	}
277	
278	// Depth of valid JSON text, counted without recursion.
279	function jsonDepth(text) {
280	  let depth = 0;
281	  let max = 0;
282	  let inString = false;
283	  for (let i = 0; i < text.length; i++) {
284	    const c = text[i];
285	    if (inString) {
286	      if (c === '\\') i++;
287	      else if (c === '"') inString = false;
288	    } else if (c === '"') {
289	      inString = true;
290	    } else if (c === '[' || c === '{') {
291	      depth++;
292	      if (depth > max) max = depth;
293	    } else if (c === ']' || c === '}') {
294	      depth--;
295	    }
296	  }
297	  return max;
298	}
299	
300	async function loadJson(arg) {
301	  const bytes = await readInput(arg);
302	  let text;
303	  try {
304	    text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
305	  } catch {
306	    throw new InputError('invalid UTF-8', 3);
307	  }
308	  let value;
309	  try {
310	    value = JSON.parse(text);
311	  } catch {
312	    throw new InputError('invalid JSON', 3);
313	  }
314	  if (jsonDepth(text) > MAX_DEPTH) throw new InputError('too deep', 3);
315	  return value;
316	}
317	
318	function fail(message, exitCode) {
319	  process.stderr.write(`${message}\n`);
320	  process.exitCode = exitCode;
321	}
322	
323	async function main(args) {
324	  const [patchArg, docArg = '-'] = args;
325	  if (args.length < 1 || args.length > 2 || (patchArg === '-' && docArg === '-')) {
326	    fail(USAGE, 2);
327	    return;
328	  }
329	  const inputs = [];
330	  for (const arg of [patchArg, docArg]) {
331	    try {
332	      inputs.push(await loadJson(arg));
333	    } catch (err) {
334	      if (!(err instanceof InputError)) throw err;
335	      fail(`Error: ${arg === '-' ? 'stdin' : arg}: ${err.message}`, err.exitCode);
336	      return;
337	    }
338	  }
339	  const [patch, doc] = inputs;
340	  let result;
341	  try {
342	    result = applyPatch(doc, patch);
343	  } catch (err) {
344	    if (!(err instanceof PatchError)) throw err;
345	    fail(`Error: ${err.message}`, 4);
346	    return;
347	  }
348	  process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
349	}
350	
351	await main(process.argv.slice(2));

