202	const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
203	const MAX_BYTES = 1048576;
204	const MAX_DEPTH = 1000;
205	
206	class CliError extends Error {
207	  constructor(message, exitCode) {
208	    super(message);
