226	  let fd;
227	  try {
228	    fd = fs.openSync(path, 'r');
229	  } catch (err) {
230	    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') throw readError(path, 'no such file');
231	    if (err.code === 'EISDIR' || isDirectory(path)) throw readError(path, 'is a directory');
232	    throw readError(path, 'cannot read');
233	  }
234	  try {
235	    if (fs.fstatSync(fd).isDirectory()) throw readError(path, 'is a directory');
236	    const chunks = [];
237	    let total = 0;
238	    for (;;) {
239	      const buf = Buffer.alloc(65536);
240	      const n = fs.readSync(fd, buf, 0, buf.length, null);
241	      if (n === 0) break;
242	      total += n;
243	      if (total > MAX_BYTES) throw readError(path, 'too large');
244	      chunks.push(buf.subarray(0, n));
245	    }
246	    return Buffer.concat(chunks);
247	  } catch (err) {
248	    if (err instanceof CliError) throw err;
249	    if (err.code === 'EISDIR') throw readError(path, 'is a directory');
250	    throw readError(path, 'cannot read');
251	  } finally {
252	    fs.closeSync(fd);
253	  }
254	}
