256	function readStdinLimited() {
257	  return new Promise((resolve, reject) => {
258	    const chunks = [];
259	    let total = 0;
260	    let stream;
261	    try {
262	      stream = process.stdin;
263	    } catch {
264	      reject(readError('stdin', 'cannot read'));
265	      return;
266	    }
267	    stream.on('data', (chunk) => {
268	      total += chunk.length;
269	      if (total > MAX_BYTES) {
270	        stream.destroy();
271	        reject(readError('stdin', 'too large'));
272	        return;
273	      }
274	      chunks.push(chunk);
275	    });
276	    stream.on('end', () => resolve(Buffer.concat(chunks)));
